    const build = {"cardVersion":"0.5.149","views":{"start":{"bodyBytes":12295,"styleBytes":9037,"scriptBytes":10692},"common":{"bodyBytes":7066,"styleBytes":20436,"scriptBytes":329213},"fish":{"bodyBytes":9008,"styleBytes":86646,"scriptBytes":527157},"update":{"bodyBytes":402,"styleBytes":5042,"scriptBytes":106594}}};
    Object.values(assets).forEach(asset => Object.freeze(asset));
